files.client.py:
from config import load


class Client:
    def __init__(self, **overrides):
        self.cfg = load(overrides)
        self.calls = 0

    def fetch(self, op):
        attempts = self.cfg["retries"] + 1
        last = None
        for _ in range(attempts):
            self.calls += 1
            try:
                return op()
            except ConnectionError as exc:
                last = exc
        raise last

