files.inventory.py:
class OutOfStock(Exception):
    pass


def reserve(stock, sku, qty):
    """Take qty units from stock. Raises OutOfStock if there are not enough."""
    try:
        if stock[sku] < qty:
            raise OutOfStock(sku)
        stock[sku] -= qty
    except Exception:
        return False
    return True

files.orders.py:
from inventory import reserve, OutOfStock


def fulfil(stock, lines):
    shipped, backordered = [], []
    for sku, qty in lines:
        try:
            reserve(stock, sku, qty)
            shipped.append(sku)
        except OutOfStock:
            backordered.append(sku)
    return shipped, backordered

hidden_tests.code:
from orders import fulfil

stock = {"bolt": 10, "nut": 1}
shipped, back = fulfil(stock, [("bolt", 4), ("nut", 3)])
assert shipped == ["bolt"], shipped
assert back == ["nut"], back
assert stock == {"bolt": 6, "nut": 1}
try:
    fulfil(stock, [("nope", 1)])
    raise SystemExit("unknown sku must raise KeyError")
except KeyError:
    pass
from audit import summarize
assert summarize(shipped, back) == "1 shipped, 1 backordered"

