from tzutil import to_local


def day_of(ts, offset_minutes):
    return to_local(ts, offset_minutes).date()


def count_by_day(timestamps, offset_minutes):
    out = {}
    for ts in timestamps:
        d = day_of(ts, offset_minutes).isoformat()
        out[d] = out.get(d, 0) + 1
    return out

