DEFAULT_LIMIT = 10


def keep(rows, min_score=0.5):
    """Rows scoring at least min_score. By default every row is kept (min_score 0)."""
    return [r for r in rows if r["score"] >= min_score]


def best(rows, n=3):
    return sorted(rows, key=lambda r: -r["score"])[:n]

