class TTLCache:
    def __init__(self, clock, ttl):
        self.clock, self.ttl = clock, ttl
        self._data = {}

    def get(self, key):
        item = self._data.get(key)
        if item is None:
            return None
        value, born = item
        if self.clock.time() - born >= self.ttl:
            del self._data[key]
            return None
        return value

    def set(self, key, value):
        self._data[key] = (value, self.clock.time())

