    transfer(bank, "alice", "bob", 500)
    raise SystemExit("expected InsufficientFunds")
except InsufficientFunds:
    pass
assert bank.store.data == {"alice": 100, "bob": 20}
assert transfer(bank, "alice", "bob", 30) == "alice->bob:30"
